impl<'i, 'arena> LoxParser<'i, 'arena> {
    /// Creates a new parser.
    /// A reference to `input` is stored in the parser for scanning.
    /// `parser_arena` is where the parser's internal objects (GSS, SPPF nodes,
    /// etc.) are allocated.
    pub fn new(input: &'i Input, parser_arena: &'arena Arena) -> Self {
        init_logger();
        let vec_arena = parser_arena;
        Self {
            vec_arena,
            scanner: LoxScanner::new(input, vec_arena),
            gss_nodes_index: LazyInlineMaps::new(31, vec_arena),
            gss_nodes_index_expr: InlineMap::Empty,
            descriptors: vec_arena.vec_with_capacity(
                input.len() as usize / DESCRIPTORS_CAPACITY_DIVISOR + DESCRIPTORS_CAPACITY_FLOOR,
            ),
            gss_nodes: vec_arena.vec_with_capacity(input.len() as usize * GSS_CAPACITY_MULTIPLIER),
            sppf_nodes: vec_arena
                .vec_with_capacity(input.len() as usize * SPPF_CAPACITY_MULTIPLIER),
            intermediate_nodes_index: LazyInlineMaps::new(215, vec_arena),
            dd_intermediate_nodes_index: LazyInlineMaps::new(182, vec_arena),
            terminal_nodes_index: LazyInlineMaps::new(44, vec_arena),
            epsilon_nodes: {
                let mut v = vec_arena.vec_with_capacity(input.len() as usize + 1);
                v.resize(input.len() as usize + 1, SPPFNodeId::NONE);
                v
            },
            #[cfg(feature = "instrument")]
            descriptors_count: 0,
            #[cfg(feature = "instrument")]
            descriptors_peak: 0,
            #[cfg(feature = "instrument")]
            ll1_call_log: vec![],
            intermediate_nodes_children: vec_arena.vec(),
            intermediate_nodes_children_map: OnceCell::new(),
            nonterminal_nodes_children: vec_arena.vec(),
            nonterminal_nodes_children_map: OnceCell::new(),
            envs: vec_arena.vec_with_capacity(input.len() as usize * ENVS_CAPACITY_MULTIPLIER),
            failures: InlineVec::Empty,
            suppress_failures: false,
            #[cfg(feature = "debug-trace")]
            trace_events: None,
        }
    }
    /// Parses the input from `start` and builds the parse tree in the given
    /// `tree_arena`. The parser is consumed. The tree lives as long as the
    /// arena lives. `start` is the start wrapper of a declared nonterminal,
    /// `grammar::START_<NAME>`, which allows layout around the input. The
    /// public entry points are the typed `parse_<name>` methods.
    fn parse<'a>(
        self,
        start: NonterminalId,
        tree_arena: &'a Arena,
    ) -> Result<ParseSuccess<ParseTree<'a>>, ParseError> {
        Parser::parse(self, start, tree_arena)
    }
    pub fn parse_program(
        self,
        tree_arena: &Arena,
    ) -> Result<ParseSuccess<&parse_tree::StartProgram<'_>>, ParseError> {
        Ok(self
            .parse(START_PROGRAM, tree_arena)?
            .map(ParseTree::unwrap_start_program))
    }
    pub fn parse_declaration(
        self,
        tree_arena: &Arena,
    ) -> Result<ParseSuccess<&parse_tree::StartDeclaration<'_>>, ParseError> {
        Ok(self
            .parse(START_DECLARATION, tree_arena)?
            .map(ParseTree::unwrap_start_declaration))
    }
    pub fn parse_function(
        self,
        tree_arena: &Arena,
    ) -> Result<ParseSuccess<&parse_tree::StartFunction<'_>>, ParseError> {
        Ok(self
            .parse(START_FUNCTION, tree_arena)?
            .map(ParseTree::unwrap_start_function))
    }
    pub fn parse_var_decl(
        self,
        tree_arena: &Arena,
    ) -> Result<ParseSuccess<&parse_tree::StartVarDecl<'_>>, ParseError> {
        Ok(self
            .parse(START_VAR_DECL, tree_arena)?
            .map(ParseTree::unwrap_start_var_decl))
    }
    pub fn parse_statement(
        self,
        tree_arena: &Arena,
    ) -> Result<ParseSuccess<&parse_tree::StartStatement<'_>>, ParseError> {
        Ok(self
            .parse(START_STATEMENT, tree_arena)?
            .map(ParseTree::unwrap_start_statement))
    }
    pub fn parse_block(
        self,
        tree_arena: &Arena,
    ) -> Result<ParseSuccess<&parse_tree::StartBlock<'_>>, ParseError> {
        Ok(self
            .parse(START_BLOCK, tree_arena)?
            .map(ParseTree::unwrap_start_block))
    }
    pub fn parse_expr(
        self,
        tree_arena: &Arena,
    ) -> Result<ParseSuccess<&parse_tree::StartExpr<'_>>, ParseError> {
        Ok(self
            .parse(START_EXPR, tree_arena)?
            .map(ParseTree::unwrap_start_expr))
    }
    #[inline(never)]
    #[allow(clippy::too_many_arguments)]
    fn create_expr(
        &mut self,
        sppf_node_id: Option<SPPFNodeId>,
        gss_node_id: GssNodeId,
        return_slot: SlotId,
        env: Option<EnvId>,
        p: i32,
    ) {
        record!(self, Call, sppf_node_id, gss_node_id, return_slot);
        let i = match sppf_node_id {
            Some(id) => self.sppf_node(id).right_extent(),
            None => self.gss_node(gss_node_id).index,
        };
        // If there is already a GSS node for this call, add an edge.
        if let Some(existing_gss_node_id) = self.get_gss_node_expr(i, p) {
            record!(self, GSSNodeFound, NonterminalId(31), i);
            self.add_edge_to_existing_gss_node(
                existing_gss_node_id,
                gss_node_id,
                sppf_node_id,
                return_slot,
                env,
            );
            return;
        }
        let alternatives = self.predict(&PREDICTION_EXPR, i);
        if !alternatives.is_empty() {
            record!(self, GSSNodeNotFound, NonterminalId(31), i);
            let new_gss_node_id = self.new_gss_node(NonterminalId(31), i);
            self.add_gss_edge(new_gss_node_id, gss_node_id, sppf_node_id, return_slot, env);
            let arena = self.vec_arena;
            let (env_id, env) = self.new_env();
            env.bind(BINDING_P, p, arena);
            self.add_first_descriptors(
                NonterminalId(31),
                i,
                new_gss_node_id,
                Some(env_id),
                alternatives,
            );
            self.add_gss_node_expr(i, p, new_gss_node_id);
        } else {
            // The call symbol precedes the return slot in its alternative, so the return slot is never
            // at the first position.
            let call_slot = LoxGrammar::previous_slot(return_slot)
                .expect("a return slot follows the call symbol");
            self.add_failure(
                i,
                call_slot,
                Some(gss_node_id),
                GLLFailureKind::NoViableAlternative(&PREDICTION_EXPR),
            );
        }
    }
    fn parse_group_0_ll1(
        &mut self,
        i: u32,
        failure_context: Option<(SlotId, Option<GssNodeId>)>,
    ) -> Option<SPPFNodeId> {
        #[cfg(feature = "instrument")]
        self.ll1_call_log.push((NonterminalId(9), i));
        let result = (|| -> Option<SPPFNodeId> {
            let matched = self.scanner.longest_match(&FIRST_SET_GROUP_0, i)?;
            match matched {
                TerminalId(7) => {
                    let mut j = i;
                    let right_child = {
                        let start = j;
                        let (end, node) =
                            self.match_terminal(TerminalId(7), start, SlotId(126), None)?;
                        j = end;
                        node
                    };
                    let left_extent = self.sppf_node(right_child).left_extent();
                    let mut current = right_child;
                    let right_child = {
                        let start = j;
                        let (end, node) =
                            self.match_terminal(TerminalId(5), start, SlotId(127), None)?;
                        j = end;
                        node
                    };
                    current = self.create_intermediate_node_ll1(
                        SlotId(127),
                        left_extent,
                        j,
                        current,
                        right_child,
                    );
                    let right_child = {
                        let start = j;
                        let (end, node) =
                            self.match_terminal(TerminalId(0), start, SlotId(128), None)?;
                        j = end;
                        node
                    };
                    current = self.create_intermediate_node_ll1(
                        SlotId(128),
                        left_extent,
                        j,
                        current,
                        right_child,
                    );
                    Some(self.add_nonterminal_node(NonterminalNode {
                        nonterminal_id: NonterminalId(9),
                        return_slot: SlotId(128),
                        span: Span {
                            left_extent,
                            right_extent: j,
                        },
                        child: current,
                        ambiguous: false,
                    }))
                }
                _ => unreachable!("LL(1) dispatch covers every terminal in FIRST_SET"),
            }
        })();
        if result.is_none() {
            if let Some((slot_id, gss_node_id)) = failure_context {
                self.add_failure(
                    i,
                    slot_id,
                    gss_node_id,
                    GLLFailureKind::UnexpectedToken(&FIRST_SET_GROUP_0),
                );
            }
        }
        result
    }
    fn get_gss_node_expr(&self, input_index: u32, p: i32) -> Option<GssNodeId> {
        self.gss_nodes_index_expr.get(&(input_index, p)).copied()
    }
    fn add_gss_node_expr(&mut self, input_index: u32, p: i32, gss_node_id: GssNodeId) {
        let arena = self.vec_arena;
        self.gss_nodes_index_expr
            .insert((input_index, p), gss_node_id, arena);
    }
    fn get_or_create_epsilon_node(&mut self, i: u32) -> SPPFNodeId {
        let existing = self.epsilon_nodes[i as usize];
        if existing != SPPFNodeId::NONE {
            record!(self, TerminalNodeFound, existing);
            return existing;
        }
        let span = Span::new(i, i);
        let terminal_id = TerminalId(42);
        let node_id = SPPFNodeId(self.sppf_nodes.len() as u32);
        record!(self, TerminalNodeCreated, terminal_id, span);
        self.sppf_nodes
            .push(SPPFNode::Terminal(TerminalNode { terminal_id, span }));
        self.epsilon_nodes[i as usize] = node_id;
        node_id
    }
}
